from dataclasses import dataclass


@dataclass
class Rect:
    w: int
    h: int


@dataclass
class Square:
    side: int


@dataclass
class Tri:
    b: int
    h: int


type Shape = Rect | Square | Tri


def area(s: Shape) -> int:
    """Calculate the area of a shape, rounded down."""
    match s:
        case Rect(w, h):
            return w * h
        case Square(side):
            return side * side
        case Tri(b, h):
            return (b * h) // 2


def test_area_rect() -> None:
    assert area(Rect(w=4, h=5)) == 20
    assert area(Rect(w=0, h=5)) == 0


def test_area_square() -> None:
    assert area(Square(side=6)) == 36
    assert area(Square(side=0)) == 0


def test_area_tri() -> None:
    assert area(Tri(b=4, h=5)) == 10
    assert area(Tri(b=3, h=3)) == 4
    assert area(Tri(b=1, h=1)) == 0

